package com.agriconnect.rescue;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.web.bind.annotation.*;@RestController class AnalyticsExportController{private final JdbcClient db;AnalyticsExportController(JdbcClient d){db=d;}@GetMapping("/internal/analytics/rescue-registrations")List<Map<String,Object>>rows(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){return db.sql("select id as \"registrationId\",crop_batch_id as \"cropBatchId\",farmer_id as \"farmerId\",rescue_point_id as \"rescuePointId\",status from rescue_registrations order by id limit :s offset :o").param("s",size).param("o",page*size).query().listOfRows();}}
